<?php
declare(strict_types=1);
namespace app\common\service\merchant;

use think\facade\Db;
use InvalidArgumentException as Invalid;
use app\common\service\WorkspaceAssetService;
use app\common\service\merchant\clip\ClipCloudJobService;

/** Metadata references only. Native generators, result files and billing remain authoritative. */
final class MerchantFilmService
{
    public static function scope(string $table,int $tenant,int $user){return Db::name($table)->where(['tenant_id'=>$tenant,'user_id'=>$user]);}
    public static function number(mixed $v,int $min=0,int $max=PHP_INT_MAX):int{if((!is_int($v)&&!(is_string($v)&&ctype_digit($v)))||(int)$v<$min||(int)$v>$max)throw new Invalid('记录标识或数值不正确');return (int)$v;}
    public static function text(mixed $v,int $max,bool $required=false):string{if(!is_string($v)||!mb_check_encoding($v,'UTF-8')||mb_strlen($v)>$max||($required&&trim($v)===''))throw new Invalid('文字内容或长度不正确');return trim($v);}
    public static function library(int $t,int $u,int $id,bool $lock=false):?array{if(!$id)return null;$row=self::scope('oem_film_library',$t,$u)->where(['id'=>$id,'delete_time'=>0])->lock($lock)->find();if(!$row)throw new Invalid('成片库不存在或无访问权限');return $row;}
    public static function libraries(int $t,int $u,array $p=[]):array{
        self::sync($t,$u);$rows=self::scope('oem_film_library',$t,$u)->where('delete_time',($p['trash']??'')==='1'?'>':'=',0)->order('id desc')->select()->toArray();
        $map=[];foreach(self::scope('oem_film_entry',$t,$u)->field('asset_ref,library_id')->select()->toArray() as $entry){try{self::asset($t,$u,$entry['asset_ref']);$map[$entry['library_id']]=($map[$entry['library_id']]??0)+1;}catch(Invalid){}}foreach($rows as &$r)$r['count']=(int)($map[$r['id']]??0);return ['lists'=>$rows,'unfiled'=>(int)($map[0]??0)];
    }
    public static function saveLibrary(int $t,int $u,array $p):array{return Db::transaction(function()use($t,$u,$p){$id=self::number($p['id']??0);$name=self::text($p['name']??'',80,true);self::scope('oem_merchant',$t,$u)->lock(true)->find();if($id)self::library($t,$u,$id,true);elseif(self::scope('oem_film_library',$t,$u)->where('delete_time',0)->count()>=200)throw new Invalid('最多200个成片库');$data=['name'=>$name,'update_time'=>time()];if($id)self::scope('oem_film_library',$t,$u)->where('id',$id)->update($data);else $id=(int)Db::name('oem_film_library')->insertGetId($data+['tenant_id'=>$t,'user_id'=>$u,'create_time'=>time()]);return ['id'=>$id];});}
    public static function recycleLibrary(int $t,int $u,array $p):void{$restore=($p['restore']??'')==='1';$id=self::number($p['id']??0,1);if(!self::scope('oem_film_library',$t,$u)->where('id',$id)->where('delete_time',$restore?'>':'=',0)->update(['delete_time'=>$restore?0:time(),'update_time'=>time()]))throw new Invalid('成片库不存在或无访问权限');}
    public static function asset(int $t,int $u,string $ref):array{
        if(preg_match('/^clip:result:([1-9][0-9]{0,10})$/D',$ref,$m)){
            $job=self::scope('oem_clip_cloud_job',$t,$u)->where(['id'=>(int)$m[1],'operation'=>'render','state'=>'success'])->find();if(!$job||!$job['output_key'])throw new Invalid('成片尚未完成或不可用');
            $doc=self::scope('oem_clip_document',$t,$u)->where(['id'=>$job['project_id'],'delete_time'=>0])->find();if(!$doc)throw new Invalid('成片所属工程已回收');return ['ref'=>$ref,'source'=>'clip','title'=>$doc['name'],'create_time'=>(int)$job['create_time'],'duration'=>(float)(json_decode($job['result_json'],true)['duration']??0),'video_url'=>'','cover_url'=>'','task_id'=>(int)$m[1]];
        }
        $a=WorkspaceAssetService::finishedVideo($t,$u,$ref);if(!$a)throw new Invalid('请选择本商家已完成且未回收的视频');$r=$a['raw'];$title='';foreach(['title','script_text','prompt'] as $k){$title=trim(preg_replace('/\s+/u',' ',(string)($r[$k]??'')));if($title!=='')break;}return ['ref'=>$ref,'source'=>$a['source'],'title'=>mb_substr($title,0,80)?:(WorkspaceAssetService::TOOL_NAMES[$a['source']]??'成片'),'create_time'=>(int)$r['create_time'],'duration'=>(float)($r['duration']??0),'video_url'=>$r['video_url'],'cover_url'=>$r['cover_url']??'','task_id'=>(int)$r['task_id']];
    }
    public static function sync(int $t,int $u):void{
        $refs=[];foreach(WorkspaceAssetService::FILM_SOURCES as $source){$prefix=WorkspaceAssetService::prefix($source);if(!$prefix)continue;
            try{$ids=self::scope($prefix.'_result',$t,$u)->where('delete_time',0)->column('id');}catch(\Throwable){continue;}foreach($ids as $id)$refs[]=$source.':result:'.$id;
        }
        foreach(self::scope('oem_clip_cloud_job',$t,$u)->where(['operation'=>'render','state'=>'success'])->field('id')->select()->toArray() as $r)$refs[]='clip:result:'.$r['id'];
        $known=array_flip(self::scope('oem_film_entry',$t,$u)->column('asset_ref'));foreach($refs as $ref){if(isset($known[$ref]))continue;try{$asset=self::asset($t,$u,$ref);}catch(Invalid){continue;}$dest=self::scope('oem_film_destination',$t,$u)->where(['source'=>$asset['source'],'task_id'=>$asset['task_id']])->order('id')->find();$lib=(int)($dest['library_id']??0);try{self::library($t,$u,$lib);}catch(Invalid){$lib=0;}Db::name('oem_film_entry')->extra('IGNORE')->insert(['tenant_id'=>$t,'user_id'=>$u,'asset_ref'=>$ref,'library_id'=>$lib,'create_time'=>time()]);}
    }
    public static function listing(int $t,int $u,array $p):array{
        self::sync($t,$u);$q=self::scope('oem_film_entry',$t,$u);if(isset($p['library_id'])&&$p['library_id']!==''){$lib=self::number($p['library_id']);self::library($t,$u,$lib);$q->where('library_id',$lib);}else{$active=self::scope('oem_film_library',$t,$u)->where('delete_time',0)->column('id');$q->whereIn('library_id',array_merge([0],$active));}
        $source=$p['source']??'';if($source!==''&&!in_array($source,[...WorkspaceAssetService::FILM_SOURCES,'clip'],true))throw new Invalid('视频来源不正确');if($source!=='')$q->whereLike('asset_ref',$source.':%');$keyword=self::text($p['keyword']??'',80);$out=[];
        $usage=MerchantFinishedCatalogService::filmUsage($t,$u);$limits=self::scope('oem_finished_library_setting',$t,$u)->where('kind','video')->column('max_uses','library_id');$want=(string)($p['usage']??'');if($want!==''&&!in_array($want,['unused','assigned','sent','full'],true))throw new Invalid('使用状态不正确');$counts=['unused'=>0,'assigned'=>0,'sent'=>0,'full'=>0];
        foreach($q->order('id desc')->select()->toArray() as $row){try{$a=self::asset($t,$u,$row['asset_ref']);}catch(Invalid){continue;}if($keyword!==''&&mb_stripos($a['title'],$keyword)===false)continue;$use=$usage[$row['asset_ref']]??['assigned'=>0,'sent'=>0,'platforms'=>[],'last_assigned'=>0,'last_sent'=>0,'tasks'=>[]];$max=(int)($limits[(int)$row['library_id']]??0);$state=MerchantFinishedCatalogService::filmState($use,$max);$counts[$state]++;if($want!==''&&$state!==$want)continue;unset($use['tasks']);$out[]=$a+['id'=>(int)$row['id'],'library_id'=>(int)$row['library_id'],'usage'=>$use+['state'=>$state,'max'=>$max]];}
        if(($p['sort']??'')==='unused'){$rank=['unused'=>0,'assigned'=>1,'sent'=>2,'full'=>3];usort($out,fn($x,$y)=>($rank[$x['usage']['state']]<=>$rank[$y['usage']['state']])?:($y['create_time']<=>$x['create_time']));}
        $size=24;$page=max(1,min((int)($p['page']??1),max(1,(int)ceil(count($out)/$size))));return ['lists'=>array_slice($out,($page-1)*$size,$size),'count'=>count($out),'page'=>$page,'page_size'=>$size,'states'=>$counts];
    }
    public static function refs(mixed $refs,int $max=100):array{if(!is_array($refs)||!array_is_list($refs)||!$refs||count($refs)>$max)throw new Invalid('请选择1至'.$max.'个成片');$pattern='/^('.implode('|',[...WorkspaceAssetService::FILM_SOURCES,'clip']).'):result:[1-9][0-9]{0,10}$/D';foreach($refs as $r)if(!is_string($r)||!preg_match($pattern,$r))throw new Invalid('成片标识不正确');return array_values(array_unique($refs));}
    public static function move(int $t,int $u,array $p):void{Db::transaction(function()use($t,$u,$p){$lib=self::number($p['library_id']??0);self::library($t,$u,$lib,true);$refs=self::refs($p['refs']??[]);foreach($refs as $ref){self::asset($t,$u,$ref);Db::name('oem_film_entry')->extra('IGNORE')->insert(['tenant_id'=>$t,'user_id'=>$u,'asset_ref'=>$ref,'library_id'=>$lib,'create_time'=>time()]);self::scope('oem_film_entry',$t,$u)->where('asset_ref',$ref)->update(['library_id'=>$lib]);}});}
    public static function intent(int $t,int $u,array $p):array{$source=self::text($p['source']??'',32);if(!in_array($source,['digital_human','pic_lipsync','image_human','clip'],true))throw new Invalid('视频来源不正确');$lib=self::number($p['library_id']??0);self::library($t,$u,$lib);$key=bin2hex(random_bytes(24));Db::name('oem_film_destination')->insert(['tenant_id'=>$t,'user_id'=>$u,'source'=>$source,'task_id'=>0,'library_id'=>$lib,'intent_key'=>$key,'create_time'=>time()]);return ['intent_key'=>$key];}
    public static function bind(int $t,int $u,array $p):array{return Db::transaction(function()use($t,$u,$p){$key=self::text($p['intent_key']??'',64,true);$dest=self::scope('oem_film_destination',$t,$u)->where('intent_key',$key)->lock(true)->find();if(!$dest||$dest['create_time']<time()-86400)throw new Invalid('归库请求已过期');$id=self::number($p['task_id']??0,1);$table=match($dest['source']){'digital_human'=>'aigc_digital_human_task','pic_lipsync'=>'aigc_pic_lipsync_task','image_human'=>'image_human_task','clip'=>'oem_clip_cloud_job'};if(!self::scope($table,$t,$u)->where('id',$id)->count())throw new Invalid('视频任务不存在或无访问权限');if($dest['task_id']&&(int)$dest['task_id']!==$id)throw new Invalid('归库请求已使用');if((int)$dest['task_id']===$id)return ['library_id'=>(int)$dest['library_id']];$old=self::scope('oem_film_destination',$t,$u)->where(['source'=>$dest['source'],'task_id'=>$id])->where('id','<>',$dest['id'])->find();if(!$old){self::scope('oem_film_destination',$t,$u)->where('id',$dest['id'])->update(['task_id'=>$id]);try{self::library($t,$u,(int)$dest['library_id']);foreach(self::scope('oem_film_entry',$t,$u)->where('library_id',0)->whereLike('asset_ref',$dest['source'].':%')->select()->toArray() as $entry){try{$a=self::asset($t,$u,$entry['asset_ref']);if($a['task_id']===$id)self::scope('oem_film_entry',$t,$u)->where('id',$entry['id'])->update(['library_id'=>$dest['library_id']]);}catch(Invalid){}}}catch(Invalid){}}return ['library_id'=>(int)($old['library_id']??$dest['library_id'])];});}
    public static function delivery(int $t,int $u,string $ref):array{$a=self::asset($t,$u,$ref);return $a['source']==='clip'?(new ClipCloudJobService())->delivery($t,$u,$a['task_id']):['url'=>$a['video_url'],'expires_in'=>0];}
}
